    content: "**Ficha completa del modelo:** <a href=/patinetes/egret-gt/>Egret GT</a> — ficha técnica, precio, garantía y mantenimiento.\nAntes de comprar, <a href=/>analiza tu multa gratis en el analizador</a> (si te multan con el patinete, comprueba si la multa es recurrible).\n\n\n<img src=/media/patinetes/egret-gt.webp alt=Egret GT patinete eléctrico>\n\n*Foto: fenrirs-bikeshop.de (internet, no oficial; licencia desconocida).*\n\n## Egret GT: lo esencial\n\nEl Egret GT es el patinete premium de la marca alemana Egret (Walberg): motor de 500 W con 1.620 W de pico, batería extraíble de 48 V 20 Ah y 100 km de autonomía declarada, con suspensión integral ajustable, ruedas de 13 pulgadas, frenos hidráulicos y localización Apple Find My.\n\n**¿Para quién es?** Para quien quiere el patinete más cómodo y premium para el día a día, con batería extraíble y gran autonomía.\n\n| Dato | Egret GT |\n|---|---|\n| Precio | desde 1.599 € (versión 15 Ah); versión 20 Ah (esta ficha): 1.899 € (Wattmoves/Amazon) |\n| Motor | 500 W (1.620 W pico) |\n| Batería | 48 V 20 Ah (extraíble, 5,9 kg) |\n| Velocidad máxima | 20 km/h (homologado en Alemania con ABE; en España a verificar homologación) |\n| Autonomía | 100 km (cifra del fabricante) |\n| Peso | 33 kg (27 kg sin batería + 5,9 kg de batería) |\n| Frenos | Frenos de disco hidráulicos |\n| Neumáticos | Neumáticos 13\" |\n| Suspensión | Suspensión integral ajustable (delantera y trasera) |\n| Carga máxima | 150 kg |\n| Garantía | 2 años (batería y general, web oficial Egret) |\n| EuroNCAP | sin datos EuroNCAP (patinetes no tienen prueba EuroNCAP) |\n\n## Precio del Egret GT\n\nEl precio recogido es **desde 1.599 € (versión 15 Ah); versión 20 Ah (esta ficha): 1.899 € (Wattmoves/Amazon)**. Es el precio documentado en las fuentes citadas al final; puede variar según tienda, versión y momento de compra. En la ficha técnica del modelo no se incluye el precio en el título, pero la página sí muestra el precio, como exige la guía de publicación.\n\n## Ficha técnica\n\nVer la ficha completa con todos los datos: <a href=/patinetes/egret-gt/>Egret GT</a>.\n\n- **Motor:** 500 W (1.620 W pico)\n- **Batería:** 48 V 20 Ah (extraíble, 5,9 kg)\n- **Velocidad máxima:** 20 km/h (homologado en Alemania con ABE; en España a verificar homologación)\n- **Autonomía:** 100 km (cifra del fabricante)\n- **Peso:** 33 kg (27 kg sin batería + 5,9 kg de batería)\n- **Frenos:** Frenos de disco hidráulicos\n- **Neumáticos:** Neumáticos 13\"\n- **Suspensión:** Suspensión integral ajustable (delantera y trasera)\n- **Carga máxima:** 150 kg\n- **Protección:** IPX5 vehículo / IPX7 batería (aboutwaves)\n\n## Autonomía y motor\n\nLa autonomía declarada es **100 km (cifra del fabricante)** con un motor de **500 W (1.620 W pico)**. En uso real, la autonomía baja con el peso del conductor, las cuestas, el frío y la velocidad: calcula entre un 60% y un 80% de la cifra declarada para planificar tus rutas.\n\n## Frenos y seguridad\n\nFrenos: **Frenos de disco hidráulicos**. Revisa las pastillas y el tacto del freno cada mes, y comprueba la presión de los neumáticos cada dos semanas. Lleva casco y, si circulas de noche, comprueba que las luces funcionan antes de salir.\n\n## Mantenimiento\n\n| Tarea | Intervalo | Detalle | Coste |\n|---|---|---|---|\n| Batería | Cada carga | Carga con el cargador original; evita dejar la batería a 0% o al 100% durante semanas; guarda el patinete en sitio seco y fresco. | orientativo: 0 € (hábitos de carga); batería de recambio según modelo, consultar taller |\n| Neumáticos | Cada 2 semanas | Revisa la presión y el dibujo de los neumáticos 13\". Los neumáticos de panal o macizos no pinchan pero se desgastan igual. | orientativo: ~20–45 € por neumático (recambio habitual) |\n| Frenos | Cada mes | Comprueba el tacto y el desgaste de frenos de disco hidráulicos; ajusta el cable o sustituye las pastillas si la frenada se alarga. | orientativo: ~10–25 € pastillas / ~30–60 € juego de frenos |\n| Tornillería y plegado | Cada mes | Aprieta los tornillos del manillar y del mecanismo de plegado; comprueba que el cierre queda firme. | orientativo: 0 € (apriete en casa) |\n| Revisión general | Cada 6-12 meses | Revisión en taller: frenos, rodamientos, conexiones y estado de la batería. | orientativo: ~40–80 € en taller |\n\nLos costes son orientativos de recambio habitual (modelo similar Egret X / Pro, misma marca); no son PVP oficiales. Consulta al taller para el precio exacto.\n\n## Historia del modelo\n\n- **Lanzamiento (IPX5 vehículo / IPX7 batería (aboutwaves) año exacto en la web oficial):** Egret GT sale al mercado dentro de la gama Egret (Walberg). Lanzamiento en 2025.\n- **Consolidación (2025-2026):** El Egret GT aparece en comparativas, tiendas y guías de compra recogidas como fuentes de esta ficha.\n- **Actualidad (2026):** Ficha y guía de compra preparadas en borrador con los datos verificados en las fuentes citadas.\n\n## Garantía\n\n2 años (batería y general, web oficial Egret).\n\n<img src=/media/patinetes/egret-gt-2.webp alt=Egret GT, vista en detalle>\n\n## Preguntas frecuentes\n\n### ¿Cuánto cuesta el Egret GT?\n\nEl precio recogido en esta ficha es desde 1.599 € (versión 15 Ah); versión 20 Ah (esta ficha): 1.899 € (Wattmoves/Amazon). El precio puede variar según tienda, versión y año; la cifra de esta página indica su fuente y no se ha inventado.\n\n### ¿Qué autonomía real tiene el Egret GT?\n\nLa autonomía declarada es 100 km (cifra del fabricante). La autonomía real depende del peso del conductor, el terreno, la temperatura y el ritmo; en ciudad, calcula entre un 60% y un 80% de la cifra declarada.\n\n### ¿Qué velocidad máxima alcanza el Egret GT?\n\nLa velocidad máxima declarada es 20 km/h (homologado en Alemania con ABE; en España a verificar homologación). En España, los vehículos de movilidad personal (VMP) están limitados a 25 km/h para circular por vías públicas.\n\n### ¿Cuánto pesa el Egret GT y cuánto puede cargar?\n\nPesa 33 kg (27 kg sin batería + 5,9 kg de batería) y admite una carga máxima de 150 kg. Comprueba el peso real con el cargador y los accesorios incluidos antes de comprarlo.\n\n### ¿Qué garantía tiene el Egret GT?\n\nGarantía: 2 años (batería y general, web oficial Egret). Guarda la factura y el número de serie; la garantía la aplica el vendedor o el distribuidor oficial.\n\n### ¿Se puede circular con el Egret GT en España?\n\nEn España, un VMP debe cumplir el Reglamento de la DGT: velocidad máxima 25 km/h, certificado de circulación y, según el municipio, seguro y casco. Las versiones de más de 25 km/h de esta ficha son para circuito privado, no para vías públicas.\n\n\n\n## Otros modelos de Egret (Walberg)\n\n- <a href=/patinetes/egret-ey-1/>egret-ey-1</a>\n- <a href=/patinetes/egret-ey-2/>egret-ey-2</a>\n- <a href=/patinetes/egret-ey-3/>egret-ey-3</a>\n- <a href=/patinetes/egret-pro/>egret-pro</a>\n- <a href=/patinetes/egret-ten-v4/>egret-ten-v4</a>\n\n- <a href=/patinetes/>Todos los patinetes</a>\n- <a href=/patinetes/egret-gt/>Ficha del modelo</a>\n\n## Fuentes\n\n- <a href=https://my-egret.com/e-models/egret-gt/>https://my-egret.com/e-models/egret-gt/</a>\n\n*Nota: las fotos de esta ficha son de internet no oficial salvo que en `fotos-fuentes.txt` se indique lo contrario, con crédito y aviso. Nunca se usa IA como foto real.*\n",
