    content: "**Ficha completa del modelo:** <a href=/patinetes/inokim-ox/>Inokim OX</a> — ficha técnica, precio, garantía y mantenimiento.\nAntes de comprar, <a href=/>analiza tu multa gratis en el analizador</a> (si te multan con el patinete, comprueba si la multa es recurrible).\n\n\n<img src=/media/patinetes/inokim-ox.webp alt=Inokim OX patinete eléctrico>\n\n*Foto: boardstore.com.au (internet, no oficial; licencia desconocida).*\n\n## Inokim OX: lo esencial\n\nEl Inokim OX es el patinete de gama media de Inokim: motor de 800 W, batería de 624 Wh y 34 km de autonomía real, con suspensión de doble goma y frenos de disco. Está por debajo del OX Super (1.210 Wh) y del OX Hero en batería y precio.\n\n**¿Para quién es?** Para quien quiere un Inokim con buena construcción y prestaciones medias, sin subir al OX Super.\n\n| Dato | Inokim OX |\n|---|---|\n| Precio | 1.499 $ (EE. UU., según Levy/ESG; precio aproximado no oficial, en España a verificar) |\n| Motor | 800 W |\n| Batería | 624 Wh |\n| Velocidad máxima | 45 km/h (28,2 mph, versión EE. UU.; en España limitado a 25 km/h) |\n| Autonomía | 34 km (21,1 millas, prueba real) |\n| Peso | 26,6 kg (58,6 lb) |\n| Frenos | Frenos de disco |\n| Neumáticos | Neumáticos 10\" |\n| Suspensión | Doble goma |\n| Carga máxima | 120 kg (265 lb) |\n| Garantía | Garantía del fabricante en modelos parecidos: 1 año (Inokim OX según scooter.guide; 2 años en OX Super según su manual) |\n| EuroNCAP | sin datos EuroNCAP (patinetes no tienen prueba EuroNCAP) |\n\n## Precio del Inokim OX\n\nEl precio recogido es **1.499 $ (EE. UU., según Levy/ESG; precio aproximado no oficial, en España a verificar)**. Es el precio documentado en las fuentes citadas al final; puede variar según tienda, versión y momento de compra. En la ficha técnica del modelo no se incluye el precio en el título, pero la página sí muestra el precio, como exige la guía de publicación.\n\n## Ficha técnica\n\nVer la ficha completa con todos los datos: <a href=/patinetes/inokim-ox/>Inokim OX</a>.\n\n- **Motor:** 800 W\n- **Batería:** 624 Wh\n- **Velocidad máxima:** 45 km/h (28,2 mph, versión EE. UU.; en España limitado a 25 km/h)\n- **Autonomía:** 34 km (21,1 millas, prueba real)\n- **Peso:** 26,6 kg (58,6 lb)\n- **Frenos:** Frenos de disco\n- **Neumáticos:** Neumáticos 10\"\n- **Suspensión:** Doble goma\n- **Carga máxima:** 120 kg (265 lb)\n- **Protección:** Sin clasificación oficial (según Levy)\n\n## Autonomía y motor\n\nLa autonomía declarada es **34 km (21,1 millas, prueba real)** con un motor de **800 W**. En uso real, la autonomía baja con el peso del conductor, las cuestas, el frío y la velocidad: calcula entre un 60% y un 80% de la cifra declarada para planificar tus rutas.\n\n## Frenos y seguridad\n\nFrenos: **Frenos de disco**. Revisa las pastillas y el tacto del freno cada mes, y comprueba la presión de los neumáticos cada dos semanas. Lleva casco y, si circulas de noche, comprueba que las luces funcionan antes de salir.\n\n## Mantenimiento\n\n| Tarea | Intervalo | Detalle | Coste |\n|---|---|---|---|\n| Batería | Cada carga | Carga con el cargador original; evita dejar la batería a 0% o al 100% durante semanas; guarda el patinete en sitio seco y fresco. | orientativo: 0 € (hábitos de carga); batería de recambio según modelo, consultar taller |\n| Neumáticos | Cada 2 semanas | Revisa la presión y el dibujo de los neumáticos . Los neumáticos de panal o macizos no pinchan pero se desgastan igual. | orientativo: ~20–45 € por neumático (recambio habitual) |\n| Frenos | Cada mes | Comprueba el tacto y el desgaste de frenos de disco; ajusta el cable o sustituye las pastillas si la frenada se alarga. | orientativo: ~10–25 € pastillas / ~30–60 € juego de frenos |\n| Tornillería y plegado | Cada mes | Aprieta los tornillos del manillar y del mecanismo de plegado; comprueba que el cierre queda firme. | orientativo: 0 € (apriete en casa) |\n| Revisión general | Cada 6-12 meses | Revisión en taller: frenos, rodamientos, conexiones y estado de la batería. | orientativo: ~40–80 € en taller |\n\nLos costes son orientativos de recambio habitual (modelo similar Inokim OX Super, misma marca); no son PVP oficiales. Consulta al taller para el precio exacto.\n\n## Historia del modelo\n\n- **Lanzamiento (120 kg (265 lb) año exacto en la web oficial):** Inokim OX sale al mercado dentro de la gama Inokim. Lanzamiento en 2018.\n- **Consolidación (2025-2026):** El Inokim OX aparece en comparativas, tiendas y guías de compra recogidas como fuentes de esta ficha.\n- **Actualidad (2026):** Ficha y guía de compra preparadas en borrador con los datos verificados en las fuentes citadas.\n\n## Garantía\n\nGarantía del fabricante en modelos parecidos: 1 año (Inokim OX según scooter.guide; 2 años en OX Super según su manual).\n\n<img src=/media/patinetes/inokim-ox-2.webp alt=Inokim OX, vista en detalle>\n\n## Preguntas frecuentes\n\n### ¿Cuánto cuesta el Inokim OX?\n\nEl precio recogido en esta ficha es 1.499 $ (EE. UU., según Levy/ESG; precio aproximado no oficial, en España a verificar). El precio puede variar según tienda, versión y año; la cifra de esta página indica su fuente y no se ha inventado.\n\n### ¿Qué autonomía real tiene el Inokim OX?\n\nLa autonomía declarada es 34 km (21,1 millas, prueba real). La autonomía real depende del peso del conductor, el terreno, la temperatura y el ritmo; en ciudad, calcula entre un 60% y un 80% de la cifra declarada.\n\n### ¿Qué velocidad máxima alcanza el Inokim OX?\n\nLa velocidad máxima declarada es 45 km/h (28,2 mph, versión EE. UU.; en España limitado a 25 km/h). En España, los vehículos de movilidad personal (VMP) están limitados a 25 km/h para circular por vías públicas.\n\n### ¿Cuánto pesa el Inokim OX y cuánto puede cargar?\n\nPesa 26,6 kg (58,6 lb) y admite una carga máxima de 120 kg (265 lb). Comprueba el peso real con el cargador y los accesorios incluidos antes de comprarlo.\n\n### ¿Qué garantía tiene el Inokim OX?\n\nGarantía: Garantía del fabricante en modelos parecidos: 1 año (Inokim OX según scooter.guide; 2 años en OX Super según su manual). Guarda la factura y el número de serie; la garantía la aplica el vendedor o el distribuidor oficial.\n\n### ¿Se puede circular con el Inokim OX en España?\n\nEn España, un VMP debe cumplir el Reglamento de la DGT: velocidad máxima 25 km/h, certificado de circulación y, según el municipio, seguro y casco. Las versiones de más de 25 km/h de esta ficha son para circuito privado, no para vías públicas.\n\n\n\n## Otros modelos de Inokim\n\n- <a href=/patinetes/inokim-ox-hero/>inokim-ox-hero</a>\n- <a href=/patinetes/inokim-ox-super/>inokim-ox-super</a>\n- <a href=/patinetes/inokim-oxo/>inokim-oxo</a>\n- <a href=/patinetes/inokim-quick-4/>inokim-quick-4</a>\n\n- <a href=/patinetes/>Todos los patinetes</a>\n- <a href=/patinetes/inokim-ox/>Ficha del modelo</a>\n\n## Fuentes\n\n- <a href=https://www.levyelectric.com/compare-scooters/compare-the-joyor-f5s-electric-scooter-and-the-inokim-ox>https://www.levyelectric.com/compare-scooters/compare-the-joyor-f5s-electric-scooter-and-the-inokim-ox</a>\n- <a href=https://www.electricscooterguides.com/review/compare-the-inokim-ox-and-the-kaabo-wolf-warrior-x>https://www.electricscooterguides.com/review/compare-the-inokim-ox-and-the-kaabo-wolf-warrior-x</a>\n\n*Nota: las fotos de esta ficha son de internet no oficial salvo que en `fotos-fuentes.txt` se indique lo contrario, con crédito y aviso. Nunca se usa IA como foto real.*\n",
